</div>
<div id="stepTitle" style="font-weight:bold"></div>
<div id="stepNarr" style="line-height:1.35"></div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC ───────────────────────────────────────────────────────────
   apex (projection centre)      → SphereGeometry(0.10)                black
   4 apex→corner edges           → CylinderGeometry(r=0.02)            black
   4 image-rectangle edges       → CylinderGeometry(r=0.02)            black
   image-plane midline           → CylinderGeometry(r=0.02)            grey #808080
   5 identical frusta            → clones of the group, x = 0,3.2,6.4,9.6,12.8
   active (moving) frustum       → same group, colour #1565c0, x = 3.2·t
   6 motion arrows               → Cylinder shaft(r=0.075) + Cone head(0.35/0.17) red
   optical axis                  → CylinderGeometry(r=0.008)           light grey
   scene points (optional)       → SphereGeometry(0.07)                dark grey
   sight rays (optional)         → Line (2-pt BufferGeometry)          grey
   image hits                    → SphereGeometry(0.035)               red
   flow view rectangle           → 4 Cylinders(r=0.02) + grey midline  black
   flow grid points 5×5          → SphereGeometry(0.03)                black
   flow vectors                  → Cylinder shaft + Cone head          red
   focus of expansion            → SphereGeometry(0.055)               black
──────────────────────────────────────────────────────────────────────────── */

const BLACK = 0x000000, GREY = 0x808080, RED = 0xff0000, BLUE = 0x1565c0;
const PX = 1.30, HY = 0.80, HZ = 0.50;          // image plane distance / half sizes
const APEX_X = [0, 3.2, 6.4, 9.6, 12.8];
const UP = new THREE.Vector3(0, 1, 0);

/* ── helpers ─────────────────────────────────────────────────────────────── */
function makeEdge(a, b, r, mat) {
  const dir = b.clone().sub(a);
  const len = dir.length();
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, 10), mat);
  m.position.copy(a).addScaledVector(dir, 0.5);
  m.quaternion.setFromUnitVectors(UP, dir.clone().normalize());
  return m;
}

function makeArrowObj(color, shaftR, headLen, headR) {
  const mat = new THREE.MeshBasicMaterial({ color });
  const g = new THREE.Group();
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(shaftR, shaftR, 1, 14), mat);
  const head = new THREE.Mesh(new THREE.ConeGeometry(headR, headLen, 20), mat);
  g.add(shaft, head);
  g.userData.setLength = (L) => {
    const s = Math.max(0.0001, L - headLen);
    shaft.scale.y = s; shaft.position.y = s / 2;
    head.position.y = s + headLen / 2;
    g.visible = L > headLen * 0.85;
  };
  g.userData.setDir = (dir) => g.quaternion.setFromUnitVectors(UP, dir.clone().normalize());
  g.userData.setDir(new THREE.Vector3(1, 0, 0));
  g.userData.setLength(1);
  return g;
}

/* ── one reusable camera frustum ─────────────────────────────────────────── */
function buildFrustum(edgeColor, midColor, r) {
  const eMat = new THREE.MeshBasicMaterial({ color: edgeColor });
  const mMat = new THREE.MeshBasicMaterial({ color: midColor });
  const g = new THREE.Group();
  const A = new THREE.Vector3(0, 0, 0);
  const C = [
    new THREE.Vector3(PX, HY, -HZ),
    new THREE.Vector3(PX, HY, HZ),
    new THREE.Vector3(PX, -HY, HZ),
    new THREE.Vector3(PX, -HY, -HZ)
  ];
  // apex dot
  g.add(new THREE.Mesh(new THREE.SphereGeometry(0.10, 20, 16), eMat));
  // four edges radiating from the apex
  C.forEach(c => g.add(makeEdge(A, c, r, eMat)));
  // image rectangle
  for (let i = 0; i < 4; i++) g.add(makeEdge(C[i], C[(i + 1) % 4], r, eMat));
  // faint vertical midline at mid-depth
  g.add(makeEdge(new THREE.Vector3(PX, -HY, 0), new THREE.Vector3(PX, HY, 0), r, mMat));
  return g;
}

/* ── the 3-D strip ───────────────────────────────────────────────────────── */
const strip = new THREE.Group();

APEX_X.forEach((x, i) => {
  const f = buildFrustum(BLACK, GREY, 0.02);
  f.position.set(x, 0, 0);
  strip.add(f);
  registerInteractive(f, {
    title: `Camera copy ${i + 1} of 5`,
    tooltip: `Camera ${i + 1}: same pose, moved +X`,
    body: 'All five frusta are the identical object translated along +X. The orientation never changes — only the position of the projection centre, so the rotation part of the motion is zero and only the forward translation T_z is non-zero.'
  });
});

// red motion arrows on the y = z = 0 axis
const arrowSpans = [[-2.4, -0.25], [1.45, 2.95], [4.65, 6.15], [7.85, 9.35], [11.05, 12.55], [14.3, 16.6]];
arrowSpans.forEach(([x0, x1]) => {
  const a = makeArrowObj(RED, 0.075, 0.35, 0.17);
  a.position.set(x0, 0, 0);
  a.userData.setDir(new THREE.Vector3(1, 0, 0));
  a.userData.setLength(x1 - x0);
  strip.add(a);
  registerInteractive(a, {
    title: 'Motion arrow (pure forward translation)',
    tooltip: 'T = (0, 0, T_z), T_z > 0',
    body: 'Every arrow lies exactly on the optical axis and points the same way the frusta face. Sideways components T_x and T_y are zero, so the image motion is purely radial.'
  });
});

// implied common optical axis (annotation)
const axisLine = makeEdge(new THREE.Vector3(-2.4, 0, 0), new THREE.Vector3(16.6, 0, 0), 0.008,
  new THREE.MeshBasicMaterial({ color: 0xbbbbbb }));
strip.add(axisLine);

// active (moving) camera
const active = buildFrustum(BLUE, 0x7fb2e5, 0.022);
active.scale.setScalar(1.03);
strip.add(active);
registerInteractive(active, {
  title: 'The moving camera',
  tooltip: 'Slides between the five copies',
  body: 'Scrub t (or press play): this camera slides straight down its own optical axis. Its axes stay parallel to themselves at every instant — pure translation.'
});

scene.add(strip);

/* ── optional scene points + sight rays ──────────────────────────────────── */
const raysGroup = new THREE.Group();
const scenePts = [];
const rayGeos = [], hitDots = [];
const ptMat = new THREE.MeshBasicMaterial({ color: 0x444444 });
const rayMat = new THREE.LineBasicMaterial({ color: 0x9aa4ad });
const hitMat = new THREE.MeshBasicMaterial({ color: RED });
[-2.5, 0, 2.5].forEach(py => {
  [-1.6, 0, 1.6].forEach(pz => {
    const P = new THREE.Vector3(17.5, py, pz);
    scenePts.push(P);
    const s = new THREE.Mesh(new THREE.SphereGeometry(0.07, 14, 12), ptMat);
    s.position.copy(P); raysGroup.add(s);
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(6), 3));
    rayGeos.push(geo);
    raysGroup.add(new THREE.Line(geo, rayMat));
    const h = new THREE.Mesh(new THREE.SphereGeometry(0.035, 12, 10), hitMat);
    hitDots.push(h); raysGroup.add(h);
  });
});

/* ── image-plane flow-field view ─────────────────────────────────────────── */
const FCX = 6.4;                      // flow view is centred here
const FW = 0.60, FH = 0.80;           // half width / half height (1.20 x 1.60)
const flowGroup = new THREE.Group();
const fEdgeMat = new THREE.MeshBasicMaterial({ color: BLACK });
const fMidMat = new THREE.MeshBasicMaterial({ color: GREY });
{
  const c = [
    new THREE.Vector3(FCX - FW, FH, 0), new THREE.Vector3(FCX + FW, FH, 0),
    new THREE.Vector3(FCX + FW, -FH, 0), new THREE.Vector3(FCX - FW, -FH, 0)
  ];
  for (let i = 0; i < 4; i++) flowGroup.add(makeEdge(c[i], c[(i + 1) % 4], 0.02, fEdgeMat));
  flowGroup.add(makeEdge(new THREE.Vector3(FCX, -FH, 0.001), new THREE.Vector3(FCX, FH, 0.001), 0.02, fMidMat));
  const foe = new THREE.Mesh(new THREE.SphereGeometry(0.055, 18, 14), fEdgeMat);
  foe.position.set(FCX, 0, 0.02);
  flowGroup.add(foe);
  registerInteractive(foe, {
    title: 'Focus of expansion',
    tooltip: 'Flow is exactly zero here',
    body: 'With T_x = T_y = 0 the image velocity is u = x·T_z/Z, v = y·T_z/Z. Both vanish at x = y = 0, so the image point straight ahead of the camera stands still: the focus of expansion.'
  });
}

const flowArrows = [], flowPts = [];
const gridMat = new THREE.MeshBasicMaterial({ color: BLACK });
for (let i = 0; i < 5; i++) {
  for (let j = 0; j < 5; j++) {
    const x = -0.48 + i * 0.24;
    const y = -0.64 + j * 0.32;
    const p = new THREE.Vector3(x, y, 0);
    flowPts.push(p);
    const dot = new THREE.Mesh(new THREE.SphereGeometry(0.03, 12, 10), gridMat);
    dot.position.set(FCX + x, y, 0.01);
    flowGroup.add(dot);
