/* ── labels (annotations) ────────────────────────────────────────────────── */
const L = {};
L.axis = addLabel('optical axis&nbsp;&mdash;&nbsp;direction of travel', new THREE.Vector3(-1.3, 0, 0), { fontSize: '12px', color: '#c00000', offset: [0, -16] });
L.apex = addLabel('projection centre <i>C</i>', new THREE.Vector3(0, 0, 0), { fontSize: '12px', offset: [-6, 22] });
