L.tz = addLabel('<b>T</b> = (0,&nbsp;0,&nbsp;T<sub>z</sub>)', new THREE.Vector3(8.0, 0, 0), { fontSize: '12px', color: '#c00000', offset: [0, -18] });
L.foe = addLabel('focus of expansion', new THREE.Vector3(FCX, 0, 0), { fontSize: '12px', offset: [0, 20] });
