const VIEW_3D = { projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 }, rollDeg: 0, target: [6.4, 0, 0], heightFraction: 0.55 };
const VIEW_FLOW = { projection: 'orthographic', axisScreenAngles: null, rollDeg: 0, target: [FCX, 0, 0], heightFraction: 0.72 };
