// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC ───────────────────────────────────────────────────────────
   apex (projection centre)      → SphereGeometry(0.10)                black
   4 apex→corner edges           → CylinderGeometry(r=0.02)            black
   4 image-rectangle edges       → CylinderGeometry(r=0.02)            black
   image-plane midline (z=0)     → CylinderGeometry(r=0.02)            grey #808080
   5 identical frusta            → clones of the group, x = 0,3.2,6.4,9.6,12.8
   moving camera (optional)      → same group, colour #1565c0, x = 3.2·t
   6 motion arrows               → Cylinder shaft(r=0.075) + Cone head(0.35/0.17) red
   optical axis (annotation)     → dashed row of Cylinders(r=0.008)    light grey
   annotation leaders            → CylinderGeometry(r=0.012)           grey
   scene points (optional)       → SphereGeometry(0.07)                dark grey
   sight rays (optional)         → Line (2-pt BufferGeometry)          grey
   image hits                    → SphereGeometry(0.035)               red
   flow view rectangle           → 4 Cylinders(r=0.02) + grey midline  black
   flow grid points 5×5          → SphereGeometry(0.03)                black
   flow vectors                  → Cylinder shaft + Cone head          red
   focus of expansion            → SphereGeometry(0.055)               black
──────────────────────────────────────────────────────────────────────────── */

const BLACK = 0x000000, GREY = 0x808080, RED = 0xff0000, BLUE = 0x1565c0;
const PX = 1.30, HY = 0.80, HZ = 0.50;          // image plane distance / half sizes
const APEX_X = [0, 3.2, 6.4, 9.6, 12.8];
const UP = new THREE.Vector3(0, 1, 0);

/* ── helpers ─────────────────────────────────────────────────────────────── */
function makeEdge(a, b, r, mat) {
  const dir = b.clone().sub(a);
  const len = Math.max(dir.length(), 1e-5);
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, 10), mat);
  m.position.copy(a).addScaledVector(dir, 0.5);
  m.quaternion.setFromUnitVectors(UP, dir.clone().normalize());
  return m;
}

function makeArrowObj(color, shaftR, headLen, headR) {
  const mat = new THREE.MeshBasicMaterial({ color });
  const g = new THREE.Group();
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(shaftR, shaftR, 1, 14), mat);
  const head = new THREE.Mesh(new THREE.ConeGeometry(headR, headLen, 20), mat);
  g.add(shaft, head);
  g.userData.setLength = (L) => {
    const s = Math.max(0.0001, L - headLen);
    shaft.scale.y = s; shaft.position.y = s / 2;
    head.position.y = s + headLen / 2;
    g.visible = L > headLen * 0.9;
  };
  g.userData.setDir = (dir) => g.quaternion.setFromUnitVectors(UP, dir.clone().normalize());
  g.userData.setDir(new THREE.Vector3(1, 0, 0));
  g.userData.setLength(1);
  return g;
}

/* ── one reusable camera frustum (identical for every copy) ──────────────── */
function buildFrustum(edgeColor, midColor, r) {
  const eMat = new THREE.MeshBasicMaterial({ color: edgeColor });
  const mMat = new THREE.MeshBasicMaterial({ color: midColor });
  const g = new THREE.Group();
  const A = new THREE.Vector3(0, 0, 0);
  const C = [
    new THREE.Vector3(PX, HY, -HZ),
    new THREE.Vector3(PX, HY, HZ),
    new THREE.Vector3(PX, -HY, HZ),
    new THREE.Vector3(PX, -HY, -HZ)
  ];
  g.add(new THREE.Mesh(new THREE.SphereGeometry(0.10, 20, 16), eMat));   // apex dot
  C.forEach(c => g.add(makeEdge(A, c, r, eMat)));                         // 4 radiating edges
  for (let i = 0; i < 4; i++) g.add(makeEdge(C[i], C[(i + 1) % 4], r, eMat)); // rectangle
  g.add(makeEdge(new THREE.Vector3(PX, -HY, 0), new THREE.Vector3(PX, HY, 0), r, mMat)); // midline
  return g;
}

/* ── the 3-D strip ───────────────────────────────────────────────────────── */
const strip = new THREE.Group();
const frusta = [];

APEX_X.forEach((x, i) => {
  const f = buildFrustum(BLACK, GREY, 0.02);
  f.position.set(x, 0, 0);
  strip.add(f);
  frusta.push(f);
  registerInteractive(f, {
    title: `Camera copy ${i + 1} of 5`,
    tooltip: `Camera ${i + 1}: same pose, translated +X`,
    body: 'All five frusta are the same object translated along the optical axis. The orientation never changes — only the position of the projection centre — so the rotation is zero and only the forward component T_z of the translation is non-zero.'
  });
});

// red motion arrows, exactly on the y = z = 0 axis
const arrowSpans = [[-2.4, -0.25], [1.45, 2.95], [4.65, 6.15], [7.85, 9.35], [11.05, 12.55], [14.3, 16.6]];
arrowSpans.forEach(([x0, x1]) => {
  const a = makeArrowObj(RED, 0.075, 0.35, 0.17);
  a.position.set(x0, 0, 0);
  a.userData.setDir(new THREE.Vector3(1, 0, 0));
  a.userData.setLength(x1 - x0);
  strip.add(a);
  registerInteractive(a, {
    title: 'Motion arrow (pure forward translation)',
    tooltip: 'T = (0, 0, T_z), T_z > 0',
    body: 'Every arrow lies on the optical axis and points the way the frusta face. The sideways components T_x and T_y are zero, so the resulting image motion is purely radial.'
  });
});

// dashed optical axis — annotation only
const axisMat = new THREE.MeshBasicMaterial({ color: 0xc2c2c2 });
const axisLine = new THREE.Group();
for (let x = -2.4; x < 16.6; x += 0.62) {
  const x1 = Math.min(x + 0.30, 16.6);
  axisLine.add(makeEdge(new THREE.Vector3(x, 0, 0), new THREE.Vector3(x1, 0, 0), 0.008, axisMat));
}
strip.add(axisLine);

// annotation leader lines (grey, shown with annotations)
const leadMat = new THREE.MeshBasicMaterial({ color: 0x9aa4ad });
const leaders = new THREE.Group();
leaders.add(makeEdge(new THREE.Vector3(0, -0.16, 0), new THREE.Vector3(0, -1.45, 0), 0.012, leadMat));
leaders.add(makeEdge(new THREE.Vector3(12.8 + PX, HY + 0.02, 0), new THREE.Vector3(12.8 + PX, HY + 0.95, 0), 0.012, leadMat));
strip.add(leaders);

// the moving camera (hidden at rest so it never doubles up with copy 1)
const active = buildFrustum(BLUE, 0x7fb2e5, 0.024);
active.visible = false;
strip.add(active);
registerInteractive(active, {
  title: 'The moving camera',
  tooltip: 'Slides along the optical axis',
  body: 'Scrub t or press play: this camera slides straight down its own optical axis. Its axes stay parallel to themselves at every instant — pure translation, no rotation.'
});

scene.add(strip);

/* ── optional scene points + sight rays ──────────────────────────────────── */
const raysGroup = new THREE.Group();
const scenePts = [];
const rayGeos = [], hitDots = [];
const ptMat = new THREE.MeshBasicMaterial({ color: 0x444444 });
const rayMat = new THREE.LineBasicMaterial({ color: 0x9aa4ad });
const hitMat = new THREE.MeshBasicMaterial({ color: RED });
[-1.8, 0, 1.8].forEach(py => {
  [-1.2, 0, 1.2].forEach(pz => {
    const P = new THREE.Vector3(16.2, py, pz);
    scenePts.push(P);
    const s = new THREE.Mesh(new THREE.SphereGeometry(0.07, 14, 12), ptMat);
    s.position.copy(P); raysGroup.add(s);
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(6), 3));
    rayGeos.push(geo);
    raysGroup.add(new THREE.Line(geo, rayMat));
    const h = new THREE.Mesh(new THREE.SphereGeometry(0.035, 12, 10), hitMat);
    hitDots.push(h); raysGroup.add(h);
  });
});

/* ── image-plane flow-field view ─────────────────────────────────────────── */
const FCX = 6.4;                      // flow view centre (x)
const FW = 0.60, FH = 0.80;           // half width / half height (1.20 x 1.60)
const flowGroup = new THREE.Group();
const fEdgeMat = new THREE.MeshBasicMaterial({ color: BLACK });
const fMidMat = new THREE.MeshBasicMaterial({ color: GREY });
{
  const c = [
    new THREE.Vector3(FCX - FW, FH, 0), new THREE.Vector3(FCX + FW, FH, 0),
    new THREE.Vector3(FCX + FW, -FH, 0), new THREE.Vector3(FCX - FW, -FH, 0)
  ];
  for (let i = 0; i < 4; i++) flowGroup.add(makeEdge(c[i], c[(i + 1) % 4], 0.02, fEdgeMat));
  flowGroup.add(makeEdge(new THREE.Vector3(FCX, -FH, 0.001), new THREE.Vector3(FCX, FH, 0.001), 0.02, fMidMat));
  const foe = new THREE.Mesh(new THREE.SphereGeometry(0.055, 18, 14), fEdgeMat);
  foe.position.set(FCX, 0, 0.02);
  flowGroup.add(foe);
  registerInteractive(foe, {
    title: 'Focus of expansion',
    tooltip: 'Image flow is exactly zero here',
    body: 'With T_x = T_y = 0 the image velocity is u = x·T_z/Z, v = y·T_z/Z. Both vanish at x = y = 0, so the image point straight ahead of the camera stands still: the focus of expansion.'
  });
}

const flowArrows = [];
const gridMat = new THREE.MeshBasicMaterial({ color: BLACK });
for (let i = 0; i < 5; i++) {
  for (let j = 0; j < 5; j++) {
    const x = -0.48 + i * 0.24;
    const y = -0.64 + j * 0.32;
    const p = new THREE.Vector3(x, y, 0);
    const dot = new THREE.Mesh(new THREE.SphereGeometry(0.03, 12, 10), gridMat);
    dot.position.set(FCX + x, y, 0.01);
    flowGroup.add(dot);
    const a = makeArrowObj(RED, 0.026, 0.10, 0.062);
    a.position.set(FCX + x, y, 0.02);
    if (p.length() > 1e-6) a.userData.setDir(new THREE.Vector3(x, y, 0));
    a.userData.setLength(0.0001);
    flowGroup.add(a);
    flowArrows.push({ a, p });
  }
}

/* ── labels ──────────────────────────────────────────────────────────────── */
const L = {};
L.axis = addLabel('optical axis &mdash; direction of travel',
  new THREE.Vector3(-1.3, 0, 0), { fontSize: '12px', color: '#c00000', offset: [0, -26] });
L.apex = addLabel('projection centre <i>C</i>',
  new THREE.Vector3(0, -1.72, 0), { fontSize: '12px' });
L.img = addLabel('image plane',
  new THREE.Vector3(12.8 + PX, HY + 1.18, 0), { fontSize: '12px' });
L.tz = addLabel('<b>T</b> = (0,&nbsp;0,&nbsp;T<sub>z</sub>) in camera coords',
  new THREE.Vector3(5.4, 0, 0), { fontSize: '12px', color: '#c00000', offset: [0, -24] });
L.mov = addLabel('moving camera',
  new THREE.Vector3(0, 0, 0), { fontSize: '12px', color: '#1565c0', offset: [0, 30] });
L.foe = addLabel('focus of expansion', new THREE.Vector3(FCX, 0, 0), { fontSize: '12px', offset: [0, 22] });
L.flowTitle = addLabel('image plane &mdash; radial flow', new THREE.Vector3(FCX, FH, 0), { fontSize: '13px', bold: true, offset: [0, -20] });
L.eq = addLabel('u = x&middot;T<sub>z</sub>/Z&nbsp;&nbsp;&nbsp;v = y&middot;T<sub>z</sub>/Z', new THREE.Vector3(FCX, -FH, 0), { fontSize: '12px', offset: [0, 22] });

function setLabelVisible(e, v) { e.div.style.visibility = v ? 'visible' : 'hidden'; }

/* ── camera framing ──────────────────────────────────────────────────────── */
// Nearly-horizontal strip: X runs ~6° below screen-right, Z recedes ~24°,
// which keeps the three-quarter read of each frustum from the source figure.
const VIEW_3D = {
  projection: 'orthographic',
  axisScreenAngles: { x: 6, z: 24 },
  rollDeg: 0,
  heightFraction: 0.92
};
const VIEW_FLOW = {
  projection: 'orthographic',
  axisScreenAngles: null,
  rollDeg: 0,
  target: [FCX, 0, 0],
  heightFraction: 0.72
};
setCameraView(VIEW_3D);

/* ── state + update ──────────────────────────────────────────────────────── */
let tPath = 0, mode = '3d', playing = false, showAnn = true, showRays = false;
const TZ = 0.5, Z0 = 6.0, ZFALL = 0.9, GAIN = 2.0;

const sliderT = document.getElementById('sliderT');
const tVal = document.getElementById('tVal');
const readout = document.getElementById('readout');

function sceneDepth(t) { return Z0 - ZFALL * t; }

function update() {
  const xa = 3.2 * tPath;
  active.position.set(xa, 0, 0);

  // the moving camera appears only once it has left the first copy
  const showActive = (mode === '3d') && (tPath > 0.02 || playing || showRays);
  active.visible = showActive;
  frusta.forEach((f, i) => { f.visible = !(showActive && Math.abs(APEX_X[i] - xa) < 0.45); });
  L.mov.pos.set(xa, -HY - 0.15, 0);
  setLabelVisible(L.mov, showActive && showAnn);

  // sight rays from the moving projection centre
  for (let i = 0; i < scenePts.length; i++) {
    const P = scenePts[i];
    const arr = rayGeos[i].attributes.position.array;
    arr[0] = xa; arr[1] = 0; arr[2] = 0;
    arr[3] = P.x; arr[4] = P.y; arr[5] = P.z;
    rayGeos[i].attributes.position.needsUpdate = true;
    rayGeos[i].computeBoundingSphere();
    const lam = PX / Math.max(P.x - xa, 1e-3);
    const hy = lam * P.y, hz = lam * P.z;
    hitDots[i].position.set(xa + PX, hy, hz);
    hitDots[i].visible = Math.abs(hy) <= HY && Math.abs(hz) <= HZ;
  }

  // radial flow field: |v| = |p| * Tz / Z
  const Z = sceneDepth(tPath);
  const s = (TZ / Z) * GAIN;
  for (const { a, p } of flowArrows) a.userData.setLength(p.length() * s);

  tVal.textContent = tPath.toFixed(2);
  if (sliderT.value !== String(tPath)) sliderT.value = tPath;
  readout.innerHTML =
    `t          = ${tPath.toFixed(2)}<br>` +
    `apex x     = ${xa.toFixed(2)}<br>` +
    `T (cam)    = (0, 0, ${TZ.toFixed(2)})<br>` +
    `Z to scene = ${Z.toFixed(2)}<br>` +
    `|v| corner = ${(1.0 * TZ / Z).toFixed(3)}`;
}

function syncLabels() {
  const a = showAnn;
  setLabelVisible(L.axis, a && mode === '3d');
  setLabelVisible(L.apex, a && mode === '3d');
  setLabelVisible(L.img, a && mode === '3d');
  setLabelVisible(L.tz, a && mode === '3d');
  setLabelVisible(L.mov, a && mode === '3d' && active.visible);
  setLabelVisible(L.foe, a && mode === 'flow');
  setLabelVisible(L.flowTitle, a && mode === 'flow');
  setLabelVisible(L.eq, a && mode === 'flow');
  axisLine.visible = a && mode === '3d';
  leaders.visible = a && mode === '3d';
}

function setMode(m) {
  if (m === mode) { syncLabels(); update(); return; }
  mode = m;
  if (m === '3d') {
    scene.remove(flowGroup);
    scene.add(strip);
    if (showRays) scene.add(raysGroup);
    setCameraView(VIEW_3D);
  } else {
    scene.remove(strip); scene.remove(raysGroup);
    scene.add(flowGroup);
    setCameraView(VIEW_FLOW);
  }
  document.getElementById('btnMode3d').classList.toggle('active', m === '3d');
  document.getElementById('btnModeFlow').classList.toggle('active', m === 'flow');
  syncLabels();
  update();
}

/* ── controls ────────────────────────────────────────────────────────────── */
let tweenState = null;

sliderT.addEventListener('input', () => { tPath = parseFloat(sliderT.value); tweenState = null; update(); });

const btnPlay = document.getElementById('btnPlay');
btnPlay.addEventListener('click', () => {
  playing = !playing;
  tweenState = null;
  btnPlay.textContent = playing ? '❚❚ Pause' : '▶ Fly forward (loop)';
  btnPlay.classList.toggle('active', playing);
  update();
});

document.getElementById('btnMode3d').addEventListener('click', () => setMode('3d'));
document.getElementById('btnModeFlow').addEventListener('click', () => setMode('flow'));

document.getElementById('chkAnn').addEventListener('change', e => { showAnn = e.target.checked; syncLabels(); update(); });
document.getElementById('chkRays').addEventListener('change', e => {
  showRays = e.target.checked;
  if (showRays && mode === '3d') scene.add(raysGroup); else scene.remove(raysGroup);
  update();
});

/* ── demo steps ──────────────────────────────────────────────────────────── */
const steps = [
  { title: '1. The camera strip at rest', narr: 'Five copies of the same camera stand in a row, each apex on the left and each image plane on the right; all frusta face the same way down one optical axis.', mode: '3d', t: 0 },
  { title: '2. Stepping forward', narr: 'Advance the slider: the active camera slides rightward from copy to copy, following the red arrows. Its orientation never changes — only its distance to the scene.', mode: '3d', t: 2 },
  { title: '3. End of the path', narr: 'At the last copy the camera is nearest the scene. The red arrow continues past it: the motion is pure translation along the viewing direction, with no rotation and no sideways component.', mode: '3d', t: 4 },
  { title: '4. What the image sees', narr: 'On the image plane the same forward motion appears as vectors expanding radially outward — zero at the focus of expansion, largest at the periphery.', mode: 'flow', t: 2 }
];
let stepIdx = 0;

function goToStep(i) {
  stepIdx = (i + steps.length) % steps.length;
  const s = steps[stepIdx];
  playing = false;
  btnPlay.textContent = '▶ Fly forward (loop)';
  btnPlay.classList.remove('active');
  setMode(s.mode);
  tweenState = { from: tPath, to: s.t, k: 0 };
  document.getElementById('stepTitle').textContent = s.title;
  document.getElementById('stepNarr').textContent = s.narr;
}
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));

/* ── own animation loop (state only) ─────────────────────────────────────── */
let lastT = performance.now();
(function loop() {
  requestAnimationFrame(loop);
  const now = performance.now();
  const dt = Math.min(0.05, (now - lastT) / 1000);
  lastT = now;
  if (tweenState) {
    tweenState.k = Math.min(1, tweenState.k + dt / 0.9);
    const k = tweenState.k;
    const e = k < 0.5 ? 2 * k * k : -1 + (4 - 2 * k) * k;
    tPath = tweenState.from + (tweenState.to - tweenState.from) * e;
    if (k >= 1) { tPath = tweenState.to; tweenState = null; }
    update();
  } else if (playing) {
    tPath += dt * 0.6;
    if (tPath > 4) tPath -= 4;
    update();
  }
})();

/* ── init ────────────────────────────────────────────────────────────────── */
document.getElementById('stepTitle').textContent = steps[0].title;
document.getElementById('stepNarr').textContent = steps[0].narr;
syncLabels();
update();
// @FIGURE_CODE_END

