  g.add(makeEdge(C[0], C[1], r, eMat));                                     // top edge
  g.add(makeEdge(C[2], C[3], r, eMat));                                     // bottom edge
  g.add(makeEdge(C[1], C[2], r * 1.28, eMat));                              // near vertical (bolder)
  g.add(makeEdge(C[3], C[0], r * 0.86, eMat));                              // far vertical (behind)
  g.add(makeEdge(C[0], C[2], r * 0.86, eMat));                              // face diagonal
  g.add(makeEdge(C[1], C[3], r * 0.86, eMat));                              // face diagonal
  g.add(makeEdge(new THREE.Vector3(PX, -HY, 0), new THREE.Vector3(PX, HY, 0), r, mMat)); // midline
  return g;
}

